const fs = require('fs');
const path = require('path');

// ============================================================
// generar_476_romper_el_bucle.js
// ============================================================
// EL BUG DE LAS CAPTURAS
// Tocar un boton volvia a preguntar lo mismo, una y otra vez:
//
//   Chiqui: ¿Quieres saber cuándo vomitó, o cuándo preocupa?
//           [¿Cuándo vomitó?] [¿Cuándo el vómito preocupa?]
//   Tú:     (toca "¿Cuándo vomitó?")
//   Chiqui: ¿Quieres saber cuándo vomitó, o cuándo preocupa?   <- otra vez
//
// LA CAUSA
// El propio boton contiene la palabra ambigua. "¿Cuándo VOMITÓ?" tiene
// "vomito", asi que el bloque de desambiguacion la volvia a capturar y
// preguntaba de nuevo. Bucle infinito.
//
// Pasaba con vomito, agua, vacunas, peso y veterinario — todo lo que
// tenia botones.
//
// EL ARREGLO
// Si la pregunta YA ES una de las opciones que ofreci, no se vuelve a
// desambiguar. Quien toco el boton ya eligio.
//
// Y DOS COSAS MAS QUE SALIERON DE AHI
//
//   "¿Está en su peso ideal?" respondia el peso REGISTRADO en vez del
//   consejo, porque los dos botones llevaban al mismo lugar. Ahora el
//   segundo dice "¿Cómo se ve un peso ideal?" y lleva al consejo.
//
//   "preocupa" pasa a contar como pregunta EDUCATIVA: quien pregunta
//   cuando preocupa un vomito quiere el criterio, no sus registros.
//
// Y SE AGREGA UN CONSEJO NUEVO sobre vomito: cuando es pasajero, cuando
// necesita veterinario, y que mirar segun el color.
//
// REQUISITO: script 475 desplegado.
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) abortar('no se encontro ' + RUTA + '.');

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes('const yaEligio')) {
  abortar('el bucle ya esta roto. Parece que este script ya se corrio.');
}
if (!actual.includes("case 'observaciones'")) {
  abortar('falta el script 475. Correlo primero.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

for (const r of ['const yaEligio', "tema: 'vomito'", 'Cómo se ve un peso ideal',
                 'preocupa|preocupante', 'Un vómito aislado']) {
  if (!comp.includes(r)) {
    abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
console.log('  OK  el bucle esta roto y el consejo de vomito existe');

// yaEligio TIENE que evaluarse antes del bloque de ambiguas, o no sirve.
const posYa = comp.indexOf('const yaEligio');
const posAmb = comp.indexOf('const amb = AMBIGUAS.find');
if (posYa > posAmb) {
  abortar('yaEligio quedaria despues de usarse: el bucle volveria.');
}
console.log('  OK  se evalua antes de desambiguar');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('Prueba tocando los botones: cada uno debe RESPONDER, no volver');
console.log('a preguntar. Y "¿Cómo se ve un peso ideal?" debe dar el consejo,');
console.log('no los kilos.');
console.log('');
console.log('Listo.');
